    def build(n, bias, maxd=5000):
        # slots: (parent, side, depth); nodes get ids 0..n-1
        left = [-1] * n
        right = [-1] * n
        slots = []
        if n == 0:
            return left, right
        depth = [1] * n
        if depth[0] < maxd:
            slots.append((0, 0))
            slots.append((0, 1))
        for v in range(1, n):
            while True:
                r = rng.random()
                if r < bias:
                    k = len(slots) - 1
                elif r < bias + (1 - bias) * 0.0 + 0.0:
                    k = 0
                else:
                    k = rng.randrange(len(slots))
                break
            p, side = slots[k]
            slots[k] = slots[-1]
            slots.pop()
            if side == 0:
                left[p] = v
            else:
                right[p] = v
            depth[v] = depth[p] + 1
            if depth[v] < maxd:
                slots.append((v, 0))
                slots.append((v, 1))
